{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '선택했으면 괜찮아야 해'라는 규칙이 단단히 자리 잡은 배경을 언급함. 내담자의 핵심 믿음 '나를 앞세우는 것은 이기적인 일이다'가 이 규칙의 근원이며, 어린 시절 내 욕구를 내세우면 '이기적이다'라는 핀잔을 받았던 경험이 이 믿음을 강화한 배경임."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "상담사가 '괜찮다는 말을 들어본 적이 없다'는 내담자의 말을 '선택했으면 괜찮아야 해' 규칙의 배경으로 연결함. '내 필요나 힘듦을 앞세우는 것은 이기적이고 부끄러운 일'이라는 태도가 이 규칙을 지탱하고 있으며, 배우자가 '당신은 뭘 원하는지 모르겠다'고 했을 때 '나는 다 괜찮아'로 얼버무린 사례가 이 태드의 현상임."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/1"],
      "relevance": "상담사가 '선택했으면 괜찮아야 해'라는 규칙 자체를 작업 대상으로 삼고 있음. '힘들어도 내색하지 않아야 한다'는 규칙이 내담자의 발언 '제가 하기로 한 거니까요'에서 직접 나타나며, 가족 모임에서 어머니가 '너는 원래 잘하니까'라고 당연하게 맡긴 상황도 이 규칙이 작동하는 맥락임."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "상담사가 '괜찮다는 말을 들어본 적이 없다'는 내담자의 진술에 반응하며, 내담자가 자기 상태를 '괜찮아요'로 숨기는 양상을 지적하고 있음. 배우자의 질문에 '나는 다 괜찮아'라고 답한 사례가 이 대처 전략의 직접적 예시임."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/1"],
      "relevance": "내담자가 아이에게 소리를 지른 뒤 '내가 왜 이러나' 싶어 죄책감을 느끼는 것이 상담의 직접적 동기이며, 이는 쌓인 피로와 서운함이 폭발한 뒤 죄책감으로 이어지는 패턴에 해당함. 가족 모임에서 당연하게 역할을 맡겨진 경험이 쌓인 서운함의 배경임."
    }
  ]
}

